// src/store/index.js
import { createStore } from "vuex";
import productStore from "./productStore"; // 导入产品 store
import userStore from "./userStore"; // 导入用户 store

const store = createStore({
  modules: {
    product: productStore, // 注册产品模块
    user: userStore, // 注册用户模块
  },
});

export default store;
